import re

def parse(lines):
    hdr = re.compile(r'^Dumping (?P<name>.+?):\s*$')
    node = re.compile(r'^(?P<prefix>[ |`-]*)(?P<kind><<<NULL>>>|[A-Za-z_]\w*)(?:\s+(?P<addr>0x[0-9a-fA-F]+))?(?:\s+<(?P<range>[^<>]*)>)?(?:\s+(?P<loc>(?:line|col):\d+(?::\d+)?|[^\s:\x27<>]+:\d+:\d+)(?=\s|$))?(?:\s+(?P<rest>.*?))?\s*$')
    func = ''
    stack = {}
    used = []
    skip = []
    recs = []
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        m = hdr.match(line)
        if m:
            func = m.group('name')
            stack = {}
            skip.append(i)
            continue
        m = node.match(line)
        if not m:
            continue
        depth = len(m.group('prefix')) // 2
        addr = m.group('addr') or ''
        parent = stack.get(depth - 1, '') if depth > 0 else ''
        stack[depth] = addr
        for d in list(stack.keys()):
            if d > depth:
                del stack[d]
        recs.append({
            'Function': func,
            'Depth': depth,
            'Parent': parent,
            'Node': m.group('kind'),
            'Address': addr,
            'Range': m.group('range') or '',
            'Location': m.group('loc') or '',
            'Details': m.group('rest') or ''
        })
        used.append(i)
    blocks = []
    if recs:
        blocks.append({'name': 'nodes', 'kind': 'table', 'lines': used, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
